#!/usr/bin/env node
// Part of phpstorm-theme-generator — see LICENSE.
/**
 * Maintainer-only. Compiles plugin-src/ForgeIconProvider.java and writes the
 * result into src/lib/icon-provider-class.js as base64, next to the source.
 *
 * Nobody who uses the generator runs this, and neither does the site build:
 * the generated file is committed. Run it again only when the Java changes.
 *
 * Needs an IntelliJ-based IDE on this machine - it supplies both the platform
 * jars to compile against and, through its bundled runtime, the compiler.
 *
 *   node scripts/compile-icon-provider.js [/path/to/PhpStorm.app]
 */
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdtempSync, rmSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, join, delimiter } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'plugin-src/ForgeIconProvider.java';
const TARGET = 'src/lib/icon-provider-class.js';
// plugin.xml says since-build 233 (2023.3), which runs on Java 17.
const RELEASE = '17';

const candidates = [process.argv[2],
  '/Applications/PhpStorm.app', '/Applications/IntelliJ IDEA.app',
  '/Applications/IntelliJ IDEA CE.app', '/Applications/WebStorm.app'].filter(Boolean);
const ide = candidates.find(p => existsSync(join(p, 'Contents/lib')) || existsSync(join(p, 'lib')));
if (!ide) {
  console.error('No IntelliJ-based IDE found. Pass its path as the first argument.');
  process.exit(1);
}
const home = existsSync(join(ide, 'Contents/lib')) ? join(ide, 'Contents') : ide;
const lib = join(home, 'lib');
const javac = [join(home, 'jbr/Contents/Home/bin/javac'), join(home, 'jbr/bin/javac'), 'javac']
  .find(p => p === 'javac' || existsSync(p));
const classpath = readdirSync(lib).filter(f => f.endsWith('.jar')).map(f => join(lib, f)).join(delimiter);

const out = mkdtempSync(join(tmpdir(), 'forge-icon-provider-'));
try {
  execFileSync(javac, ['--release', RELEASE, '-cp', classpath, '-d', out, join(root, SOURCE)],
    { stdio: 'inherit' });
  const bytes = readFileSync(join(out, 'forge/ForgeIconProvider.class'));
  const b64 = bytes.toString('base64').replace(/(.{100})/g, '$1\n');
  const java = readFileSync(join(root, SOURCE), 'utf8');
  writeFileSync(join(root, TARGET),
`// Part of phpstorm-theme-generator — see LICENSE.
// GENERATED by scripts/compile-icon-provider.js from ${SOURCE} — do not edit.
// Java ${RELEASE} bytecode, ${bytes.length} bytes.

export const ICON_PROVIDER_CLASS_NAME = 'forge.ForgeIconProvider';

export const ICON_PROVIDER_JAVA = ${JSON.stringify(java)};

const ICON_PROVIDER_B64 = \`
${b64}
\`;

export function iconProviderClassBytes() {
  const bin = atob(ICON_PROVIDER_B64.replace(/\\s+/g, ''));
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
`);
  console.log(`${TARGET}  (${bytes.length} bytes, Java ${RELEASE}, compiled against ${ide})`);
} finally {
  rmSync(out, { recursive: true, force: true });
}
